    19→
    20→    const nextRun = new Date(now)
    21→    nextRun.setHours(hours, minutes, 0, 0)
    22→
    23→    // If the time has already passed today, move to next occurrence
    24→    if (nextRun <= now) {
    25→        if (frequency === 'daily') {
    26→            nextRun.setDate(nextRun.getDate() + 1)
    27→        } else if (frequency === 'weekly') {
    28→            nextRun.setDate(nextRun.getDate() + 7)
    29→        } else if (frequency === 'monthly') {
    30→            nextRun.setMonth(nextRun.getMonth() + 1)
    31→            nextRun.setDate(1) // First of next month
    32→        }
    33→    } else if (frequency === 'weekly') {
    34→        // Set to next Sunday (0 = Sunday)
    35→        const daysUntilSunday = (7 - nextRun.getDay()) % 7
    36→        if (daysUntilSunday > 0 || nextRun <= now) {
    37→            nextRun.setDate(nextRun.getDate() + (daysUntilSunday || 7))
    38→        }
    39→    } else if (frequency === 'monthly') {
    40→        // Set to first of next month if time has passed
    41→        if (nextRun <= now || nextRun.getDate() !== 1) {
    42→            nextRun.setMonth(nextRun.getMonth() + 1)
    43→            nextRun.setDate(1)
    44→        }
    45→    }
    46→
