   442→export function useRestorePreview(): UseRestorePreviewResult {
   443→    const [loading, setLoading] = useState(false);
   444→    const [error, setError] = useState<string | null>(null);
   445→    const [data, setData] = useState<BackupPreview | null>(null);
   446→
   447→    const previewBackup = useCallback(async (options: RestorePreviewOptions): Promise<BackupPreview> => {
   448→        setLoading(true);
   449→        setError(null);
   450→
   451→        try {
   452→            const res = await fetch(buildControlServerUrl('/api/restore/preview'), {
   453→                method: 'POST',
   454→                headers: {
   455→                    'Content-Type': 'application/json',
   456→                    ...controlServerAuthHeaders(),
   457→                },
   458→                body: JSON.stringify(options),
   459→            });
   460→
   461→            if (!res.ok) {
   462→                const body = await res.text().catch(() => '');
   463→                throw new Error(`Failed to preview backup (HTTP ${res.status}): ${body || res.statusText}`);
   464→            }
   465→
   466→            const result = await res.json();
   467→
   468→            if (!result.success) {
   469→                throw new Error(result.error || 'Failed to preview backup');
   470→            }
   471→
   472→            const preview: BackupPreview = result.preview;
   473→            setData(preview);
   474→            return preview;
   475→        } catch (err) {
   476→            const errorMsg = getErrorMessage(err);
   477→            setError(errorMsg);
   478→            throw new Error(errorMsg);
   479→        } finally {
   480→            setLoading(false);
   481→        }
   482→    }, []);
   483→
   484→    return { previewBackup, loading, error, data };
