   241→/**
   242→ * Hook for polling backup progress
   243→ */
   244→export function useBackupProgress(): UseBackupProgressResult {
   245→    const [progress, setProgress] = useState<BackupProgress | null>(null);
   246→    const [loading, setLoading] = useState(false);
   247→    const [error, setError] = useState<string | null>(null);
   248→    const [isPolling, setIsPolling] = useState(false);
   249→    const intervalRef = useRef<NodeJS.Timeout | null>(null);
   250→    const backupIdRef = useRef<string | null>(null);
   251→
   252→    const fetchProgress = useCallback(async (backupId: string) => {
   253→        try {
   254→            const res = await fetch(buildControlServerUrl(`/api/backup/status/${backupId}`), {
   255→                headers: { ...controlServerAuthHeaders() },
   256→            });
   257→
   258→            if (!res.ok) {
   259→                const body = await res.text().catch(() => '');
   260→                throw new Error(`Failed to fetch backup progress (HTTP ${res.status}): ${body || res.statusText}`);
   261→            }
   262→
   263→            const result = await res.json();
   264→
   265→            if (!result.success) {
   266→                throw new Error(result.error || 'Failed to fetch backup progress');
   267→            }
   268→
   269→            setProgress(result.progress);
   270→            setError(null);
   271→
   272→            // Stop polling if backup is completed or failed
   273→            if (result.progress.status === 'completed' || result.progress.status === 'failed') {
   274→                if (intervalRef.current) {
   275→                    clearInterval(intervalRef.current);
   276→                    intervalRef.current = null;
   277→                    setIsPolling(false);
   278→                }
   279→            }
   280→        } catch (err) {
   281→            const errorMsg = getErrorMessage(err);
   282→            setError(errorMsg);
   283→        }
   284→    }, []);
   285→
   286→    const startPolling = useCallback((backupId: string, interval: number = 1000) => {
   287→        // Stop existing polling if any
   288→        if (intervalRef.current) {
   289→            clearInterval(intervalRef.current);
   290→        }
   291→
   292→        backupIdRef.current = backupId;
   293→        setIsPolling(true);
   294→        setLoading(true);
   295→
   296→        // Fetch immediately
   297→        fetchProgress(backupId).finally(() => setLoading(false));
   298→
   299→        // Start polling
   300→        intervalRef.current = setInterval(() => {
   301→            fetchProgress(backupId);
   302→        }, interval);
   303→    }, [fetchProgress]);
   304→
   305→    const stopPolling = useCallback(() => {
   306→        if (intervalRef.current) {
   307→            clearInterval(intervalRef.current);
   308→            intervalRef.current = null;
   309→        }
   310→        setIsPolling(false);
   311→        backupIdRef.current = null;
   312→    }, []);
   313→
   314→    // Cleanup on unmount
   315→    useEffect(() => {
   316→        return () => {
   317→            if (intervalRef.current) {
   318→                clearInterval(intervalRef.current);
   319→            }
   320→        };
   321→    }, []);
   322→
   323→    return { progress, loading, error, startPolling, stopPolling, isPolling };
   324→}
